function mapPaper(short){const s=st();return '<article class="e-paper"><header><span>PROTECT-12</span><b>SYNTHETISCHES MUSTER</b></header><h2>'+(short?'Kurze Kontaktkarte':'Notfallmappe')+'</h2><p>'+esc(caseData().title)+'</p><section><h3>Vereinbarte Kontakte</h3>'+s.people.map(p=>'<p><b>'+esc(p.name)+'</b><br>'+esc(p.role)+'<br>'+esc(p.contact)+'</p>').join('')+'</section><section><h3>Dokumentenorte</h3>'+s.documents.map(p=>'<p><b>'+esc(p.title)+'</b>: '+esc(p.place)+'</p>').join('')+'</section><section><h3>Rückmeldung und Ersatzweg</h3><p>'+esc(s.cardRoute)+'</p></section>'+(!short?'<section><h3>Vor der Nutzung prüfen</h3><p>Zustimmung, Zugriff, Aktualität und Verständnis bestätigen. Amtliche Hinweise und nötige Fachhilfe bleiben maßgeblich.</p></section><section><h3>Offene nächste Schritte</h3>'+s.tasks.filter(t=>!t.done&&!t.paused).slice(0,3).map(t=>'<p>'+esc(t.id)+': '+esc(t.title)+'</p>').join('')+'</section>':'')+'<footer>Aus dem öffentlichen Funktionsmuster erstellt.</footer></article>';}
function documentView(){return help('Die Unterlagen übernehmen den aktiven Musterarbeitsstand. Integrierte Bestandteile und fallbezogene Ergänzungen sind gekennzeichnet.')+'<div class="f-document-index">'+D.documents.map(d=>'<button type="button" data-f-document="'+d.id+'"><span>'+esc(d.group)+'</span><b>'+esc(d.title)+'</b><small>'+esc(d.format)+'</small></button>').join('')+'</div>';}
function businessView(){return help('Ein betrieblicher Zusatz benötigt eigene Analysedaten. Die öffentliche Ansicht zeigt die getrennte Struktur ohne erfundene Betriebskennzahlen.')+(current==='c'?'<h3>Muster C: Familie und Betrieb getrennt betrachten</h3><div class="f-function-chain"><span>Private Bedürfnisse</span><span>Betriebliche Funktionen</span><span>Eindeutige Ressourcen</span><span>Benannte Verantwortung</span></div><p>Ein Bestand wird einem konkreten Standort und Zweck zugeordnet. Verfügbarkeit für Familie und Betrieb darf nicht doppelt vorausgesetzt werden.</p>'+btn('Betrieblichen Planungsstandort öffnen','data-f-action="business-stock"'):'<h3>Für dieses Muster sind keine Betriebsdaten hinterlegt.</h3><p>Es wird kein betrieblicher Bericht erzeugt. Muster C zeigt die separate Struktur.</p>');}
function backupView(){return help('Die Sicherung muss zu diesem Muster und Format passen. Vor gültiger Übernahme wird der bisherige Stand als Sicherung heruntergeladen.')+'<div class="e-work-facts">'+fact('Speicherbereich','Öffentliche Demo · Muster '+current.toUpperCase())+fact('Format','protect12-public-workspace / 2')+fact('Übertragung','Keine')+'</div>'+btn('Arbeitsstand herunterladen','data-f-action="export-state"')+'<label class="e-field">Sicherungsdatei auswählen<input type="file" accept="application/json,.json" data-f-import-file></label>'+note('Alternativ: Sicherungsinhalt einfügen','','data-f-import-text')+btn('Geprüfte Sicherung übernehmen','data-f-action="import-state"',true)+'<p data-f-import-result role="status"></p><details class="e-work-details"><summary>Was wird erhalten und geprüft?</summary><p>Aufgaben, Profile, Bestände, Packliste, Übungen, Kontakte, Dokumentenorte und Notizen gehören zur Sicherung. Format, Musterkennung, Datentypen und Grenzen werden geprüft. Fremde Kundensicherungen werden abgewiesen. Keine automatische Synchronisierung, keine Speicherung auf einem Server.</p></details>';}
