if(id==='vorratsplan')extra='<h3>Aktuelle Planungsbasis</h3><p>'+esc(s.days)+' Planungstage. Persönliche Tageswerte sind eingegebene Annahmen.</p>'+table(['Person / Profil','Standort','Tagesannahme kcal'],s.profiles.map(p=>[p.name+' · '+p.kind,p.site,p.daily||'Unbekannt']))+'<h3>Bestände mit Lagerort und Haltbarkeit</h3>'+table(['Position','Standort / Lagerort','Menge / Einheit','Packungsgewicht','MHD','kcal / 100 g','Status'],s.foods.map(r=>[r.name,r.site+' / '+r.place,r.amount+' '+r.mode,r.packGrams||'Nicht angegeben',r.mhd||'Offen',r.kcal||'Unbekannt',r.archived?'Archiviert':'Aktiv']))+'<h3>Nährwertangaben je 100 Gramm</h3>'+table(['Position','Protein','Fett','Kohlenhydrate','Ballaststoffe','Salz'],s.foods.map(r=>[r.name,...['protein','fat','carbs','fiber','salt'].map(k=>r[k]===''?'Unbekannt':r[k]+' g')]))+'<p>Die Bedienansicht rechnet nur den gewählten Standort. Die Tabelle dokumentiert die Eingaben und bestätigt keine vollständige Versorgung.</p>';
if(id==='packliste')extra=table(['Position','Zuordnung','Tasche','Stück','Gramm je Stück','Gepackt'],s.pack.map(r=>[r.name,r.owner,r.bag,r.quantity,r.grams||'Unbekannt',r.packed?'Ja':'Nein']));
if(id==='uebungen')extra=s.exercises.map(e=>{const x=exercises[e.id];return '<section><h3>'+x[0]+'</h3>'+table(['Prüfpunkt','Angabe'],[['Zweck',x[1]],['Voraussetzung',x[2]],['Erfolgskriterium',x[3]],['Termin',e.date||'Offen'],['Beteiligte',e.people||'Offen'],['Beobachtung',e.note||'Noch nicht dokumentiert'],['Arbeitsstand',e.done?'Als abgeschlossen markiert':'Offen']])+'</section>'}).join('');
if(id==='beschaffung')extra=table(['Bereich / Standort','Ergänzung','Priorität','Bedingung','Alternative','Notiz'],shop.map(x=>[x.module+' / '+x.site,x.name,x.priority,x.condition,x.alternative,s.buyNotes[x.id]||'']));
if(id==='spof')extra=Object.values(spofs).map(x=>'<section><h3>'+x[0]+'</h3>'+table(['Betroffene Funktion','Weiterer Prüfbedarf'],x.slice(1,4).map(y=>[y,x[4]]))+'</section>').join('');
if(id==='szenarien')extra=table(['Szenario','Endpunkte ab Ereignisbeginn','Prüfauftrag'],scenarioNames.map(n=>[n,'3, 14, 28, 90, 180, 365 Tage','Funktion, Bedarf, Ressourcen, Zugang, Personen und Nachweis unter diesen Bedingungen prüfen.']))+'<h3>Persönlicher Bezug im Muster</h3><p>'+esc(c.question)+'</p><p>'+esc(c.action)+'</p>';
