const renderers={start:overview,analyse:analysis,standort:locationView,spof:spofView,szenarien:scenarioView,pace:paceView,umsetzung:taskView,vorrat:foodView,packliste:packView,uebungen:exerciseView,einkauf:shoppingView,mappe:mapView,unterlagen:documentView,betrieb:businessView,sicherung:backupView};
function render(){st();all('[data-f-tab]',root).forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.fTab===view)));q('[data-f-title]',root).textContent=q('[data-f-tab="'+view+'"]',root).textContent;q('[data-f-view]',root).innerHTML=renderers[view]();foodSummary();packSummary();root.dataset.view=view;root.dataset.case=current;if(!initialRender&&window.history&&typeof window.history.replaceState==='function'){window.history.replaceState(null,'','#p12demo='+view+'&module='+moduleId+'&section='+analysisSection+'&case='+current);}initialRender=false;}
