function validateImport(text){if(typeof text!=='string'||text.length>500000)throw Error('Datei fehlt oder ist zu groß.');const x=JSON.parse(text);const forbidden=['__proto__','prototype','constructor'];function safe(v,depth=0){if(depth>10)throw Error('Datenstruktur zu tief.');if(v&&typeof v==='object'){for(const [k,val] of Object.entries(v)){if(forbidden.includes(k))throw Error('Unzulässiger Objektschlüssel.');safe(val,depth+1)}}else if(typeof v==='number'&&!Number.isFinite(v))throw Error('Ungültige Zahl.');else if(typeof v==='string'&&(v.length>2000||/[\u0000-\u0008]/.test(v)))throw Error('Ungültiger Text.');}safe(x);if(x.schema!=='protect12-public-workspace'||x.version!==2||x.demoId!=='protect12-public-demo-v2'||x.caseId!==current)throw Error('Format, Version oder Musterkennung passt nicht.');const w=x.workspace;if(!w||typeof w!=='object'||Array.isArray(w))throw Error('Arbeitsstand fehlt.');const lists={tasks:['id','module','title','done','paused','person','date','note','period'],profiles:['id','name','kind','daily','site'],foods:['id','name','amount','mode','packGrams','kcal','protein','fat','carbs','fiber','salt','site','place','mhd','archived'],pack:['id','name','quantity','grams','owner','bag','packed'],exercises:['id','date','people','note','done'],people:['id','name','role','contact'],documents:['id','title','place']};const allowed=[...Object.keys(lists),'days','cardRoute','buyNotes'];if(Object.keys(w).some(k=>!allowed.includes(k))||allowed.some(k=>!(k in w)))throw Error('Unbekannte oder fehlende Bereiche.');for(const [list,fields] of Object.entries(lists)){if(!Array.isArray(w[list])||w[list].length>100||(list==='tasks'&&w[list].length!==12)||(list==='exercises'&&w[list].length!==3))throw Error('Ungültige Liste: '+list);const ids=new Set();for(const row of w[list]){if(!row||typeof row!=='object'||Array.isArray(row)||fields.some(k=>!(k in row))||Object.keys(row).some(k=>!fields.includes(k)))throw Error('Ungültige Zeile: '+list);for(const key of fields){if(['done','paused','archived','packed'].includes(key)){if(typeof row[key]!=='boolean')throw Error('Ungültiger Status.')}else if(typeof row[key]!=='string')throw Error('Ungültiger Feldtyp.')}if(!/^[A-Za-z0-9_-]{1,80}$/.test(row.id)||ids.has(row.id))throw Error('Doppelte oder fehlende ID.');ids.add(row.id);if(list==='tasks'&&(!D.modules.some(m=>m.id===row.module)||row.id!==current+'-'+row.module||!['Zuerst','Danach'].includes(row.period)))throw Error('Aufgabenzuordnung passt nicht.');if(list==='exercises'&&!Object.keys(exercises).includes(row.id))throw Error('Unbekannte Übung.');if('site'in row&&!['Zuhause','Zweiter Ort','Betrieb'].includes(row.site))throw Error('Unbekannter Standort.');if(list==='profiles'&&!['Erwachsen','Kind / Jugendlich','Individuell'].includes(row.kind))throw Error('Unbekannter Profiltyp.');if(list==='foods'&&!['pack','kg'].includes(row.mode))throw Error('Unbekannte Einheit.');const ranges={daily:[1,10000],amount:[0,10000],packGrams:[1,100000],kcal:[0,10000],protein:[0,10000],fat:[0,10000],carbs:[0,10000],fiber:[0,10000],salt:[0,10000],quantity:[0,1000],grams:[0,100000]};for(const [k,[lo,hi]] of Object.entries(ranges)){if(k in row&&row[k]!==''&&(!Number.isFinite(Number(row[k]))||Number(row[k])<lo||Number(row[k])>hi||!/^\d+(?:\.\d+)?$/.test(row[k])||(['daily','packGrams','quantity','grams'].includes(k)&&!Number.isInteger(Number(row[k])))))throw Error('Ungültige Menge: '+k);}}}
if(typeof w.days!=='string'||(w.days!==''&&(!/^\d+$/.test(w.days)||!Number.isInteger(Number(w.days))||Number(w.days)<1||Number(w.days)>365))||typeof w.cardRoute!=='string'||!w.buyNotes||typeof w.buyNotes!=='object'||Array.isArray(w.buyNotes)||Object.entries(w.buyNotes).some(([k,v])=>!shop.some(s=>s.id===k)||typeof v!=='string'))throw Error('Ungültige Planungsangaben.');return JSON.parse(JSON.stringify(w));}
function importText(text){try{const imported=validateImport(text);exportState();states[current]=imported;render();live('Sicherung geprüft und übernommen. Der vorherige Stand wurde zuerst heruntergeladen.');return {ok:true};}catch(e){live('Import abgewiesen: '+e.message);const out=root&&q('[data-f-import-result]',root);if(out)out.textContent='Import abgewiesen. '+e.message+' Der vorhandene Arbeitsstand bleibt erhalten.';return {ok:false,error:e.message}}}
