if(!root)return;
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const ds=b.dataset;if(ds.fTab){go(ds.fTab);return}if(ds.fGo){go(ds.fGo);return}if(ds.fModule){moduleId=ds.fModule;analysisSection='ueberblick';go('analyse');return}if(ds.fSection){analysisSection=ds.fSection;render();return}if(ds.fCriterionMode){criterionMode=ds.fCriterionMode;render();return}if(ds.fPace){paceId=ds.fPace;render();return}if(ds.fSpof){spof=ds.fSpof;render();return}if(ds.fWindow){windowDays=Number(ds.fWindow);render();return}if(ds.fDocument){showPaper(documentHtml(ds.fDocument));return}if(ds.fLayer){const x=layers[ds.fLayer];q('[data-f-pin-one]',root).textContent=x[0];q('[data-f-pin-two]',root).textContent=x[1];q('[data-f-layer-title]',root).textContent=x[2];q('[data-f-layer-text]',root).textContent=x[3];all('[data-f-layer]',root).forEach(a=>a.classList.toggle('secondary',a!==b));return}if('fTheme'in ds){const light=root.classList.toggle('e-work-light');b.setAttribute('aria-pressed',String(light));b.textContent=light?'Dunkle Ansicht':'Helle Ansicht';return}if('fMenu'in ds){const open=root.classList.toggle('f-menu-open');b.setAttribute('aria-expanded',String(open));return}if('fSave'in ds){exportState();return}
const s=st(),id='new-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);switch(ds.fAction){case'module-task':taskModule=moduleId;taskFilter='alle';go('umsetzung');break;case'module-pace':paceId=moduleId;go('pace');break;case'business-stock':stockSite='Betrieb';go('vorrat');break;case'add-profile':s.profiles.push({id,name:'Weiteres Musterprofil',kind:'Individuell',daily:'',site:stockSite});render();break;case'add-food':s.foods.push({id,name:'Neue Musterposition',amount:'',mode:'pack',packGrams:'',kcal:'',protein:'',fat:'',carbs:'',fiber:'',salt:'',site:stockSite,place:'',mhd:'',archived:false});render();break;case'add-pack':s.pack.push({id,name:'Neue Packposition',quantity:'1',grams:'',owner:'Gemeinsam',bag:'Noch offen',packed:false});render();break;case'add-person':s.people.push({id,name:'Weiterer Musterkontakt',role:'',contact:''});render();break;case'add-place':s.documents.push({id,title:'Weitere Unterlage',place:''});render();break;case'print-map':showPaper(mapPaper(false));break;case'print-card':showPaper(mapPaper(true));break;case'export-state':exportState();break;case'import-state':importText(q('[data-f-import-text]',root).value);break;case'export-tasks':download('Protect12_Muster_Massnahmen.txt',s.tasks.map(t=>[t.id,t.module,t.period,t.done?'Bearbeitet':'Offen',t.paused?'Pausiert':'Aktiv',t.person,t.date,t.title,t.note].join(' | ')).join('\n'),'text/plain');break;case'export-shop':{const cell=v=>'"'+String(v).replace(/^([\s]*[=+@-]|[\t\r\n])/,"'$1").replace(/"/g,'""')+'"';download('Protect12_Muster_Beschaffung.csv',[['Bereich','Standort','Priorität','Ergänzung','Bedingung','Alternative'],...filteredShop().map(x=>[x.module,x.site,x.priority,x.name,x.condition,x.alternative])].map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv');break}}});
function edit(e){const el=e.target,ds=el.dataset,s=st();if(ds.edit){const row=s[ds.edit]?.find(x=>x.id===ds.id);if(row&&Object.hasOwn(row,ds.key)){if(ds.edit==='profiles'&&ds.key==='kind'&&row.kind!==el.value){row.daily='';const dayField=q('[data-edit="profiles"][data-id="'+row.id+'"][data-key="daily"]',root);if(dayField)dayField.value='';}row[ds.key]=el.type==='checkbox'?el.checked:el.value;foodSummary();packSummary();live('Musterarbeitsstand aktualisiert.')}}if(ds.state&&Object.hasOwn(s,ds.state)){s[ds.state]=el.value;foodSummary()}if(ds.buyNote)s.buyNotes[ds.buyNote]=el.value;if('fSearch'in ds){shopSearch=el.value;q('[data-f-shop-results]',root).innerHTML=shoppingRows();}}
root.addEventListener('input',edit);root.addEventListener('change',e=>{edit(e);const el=e.target,k=el.dataset.fSelect;if(k){({module:v=>moduleId=v,scenario:v=>scenario=Number(v),taskFilter:v=>taskFilter=v,taskModule:v=>taskModule=v,taskPeriod:v=>taskPeriod=v,stockSite:v=>stockSite=v,exercise:v=>exerciseId=v,shopModule:v=>shopModule=v,shopSite:v=>shopSite=v,shopPriority:v=>shopPriority=v})[k]?.(el.value);render()}if('fCase'in el.dataset){current=el.value;st();render();live('Eigenständiger Arbeitsstand für Muster '+current.toUpperCase()+'.')}if('fImportFile'in el.dataset&&el.files?.[0]){const file=el.files[0];if(file.size>500000){live('Import abgewiesen: Datei zu groß.');return}file.text().then(importText).catch(()=>live('Datei konnte nicht gelesen werden.'))}});
const hash=(window.location.hash||'').match(/^#p12demo=([a-z]+)&module=(M\d{2})&section=([a-z]+)&case=([abc])$/);if(hash&&renderers[hash[1]]&&D.modules.some(m=>m.id===hash[2])&&sections.some(s=>s[0]===hash[3])){view=hash[1];moduleId=hash[2];analysisSection=hash[3];current=hash[4];q('[data-f-case]',root).value=current;}
